import { isIP } from "node:net";
import { Role } from "@fpr/contracts";
import { accessKeys, type Db } from "@fpr/db";
import {
  type BetterAuthOptions,
  type BetterAuthRateLimitRule,
  betterAuth,
} from "better-auth";
import {
  APIError,
  createAuthMiddleware,
  getIP,
  getSessionFromCtx,
} from "better-auth/api";
import type { Logger } from "pino";

/**
 * Better Auth's tables as FPR stores them: every column in snake_case, ids
 * generated by Postgres, and FPR's own columns on `user`. Better Auth's `name`
 * and `image` are FPR's `display_name` and `avatar_key`. The migration that
 * creates these tables is generated from this schema.
 */
export const authSchema = {
  advanced: { database: { generateId: "uuid" } },
  user: {
    fields: {
      name: "display_name",
      image: "avatar_key",
      emailVerified: "email_verified",
      createdAt: "created_at",
      updatedAt: "updated_at",
    },
    additionalFields: {
      role: { type: "string", required: true, input: false },
      color: { type: "number", required: true, input: false },
      locale: { type: "string", required: false, input: false },
      onboardedAt: {
        type: "date",
        required: false,
        input: false,
        fieldName: "onboarded_at",
      },
    },
  },
  session: {
    fields: {
      expiresAt: "expires_at",
      createdAt: "created_at",
      updatedAt: "updated_at",
      ipAddress: "ip_address",
      userAgent: "user_agent",
      userId: "user_id",
    },
  },
  account: {
    fields: {
      accountId: "account_id",
      providerId: "provider_id",
      userId: "user_id",
      accessToken: "access_token",
      refreshToken: "refresh_token",
      idToken: "id_token",
      accessTokenExpiresAt: "access_token_expires_at",
      refreshTokenExpiresAt: "refresh_token_expires_at",
      createdAt: "created_at",
      updatedAt: "updated_at",
    },
  },
  verification: {
    fields: {
      expiresAt: "expires_at",
      createdAt: "created_at",
      updatedAt: "updated_at",
    },
  },
} as const satisfies Pick<
  BetterAuthOptions,
  "advanced" | "user" | "session" | "account" | "verification"
>;

/** Where Better Auth's endpoints are served: `/api/auth/*`. */
export const authBasePath = "/api/auth";

/** How long a session lasts: 30 days, extended on use. */
export const sessionMaxAgeSeconds = 30 * 24 * 60 * 60;

/** How often a session in use is extended: once a day at most. */
const sessionUpdateAgeSeconds = 24 * 60 * 60;

/** Password sign-ins each client address may try per window. */
export const signInRateLimit = { window: 60, max: 5 } as const;

/** Where Better Auth reads the client's address: the one `web` sets. */
const clientAddressHeader = "x-forwarded-for";

const ipAddressOptions = {
  ipAddressHeaders: [clientAddressHeader],
} as const satisfies NonNullable<
  NonNullable<BetterAuthOptions["advanced"]>["ipAddress"]
>;

/**
 * The client address Better Auth keeps a request's rate limit for, or
 * `null` when the request has none: `X-Forwarded-For` must hold a single
 * IP address.
 */
function clientAddress(request: Request): string | null {
  const forwarded = request.headers.get(clientAddressHeader)?.trim() ?? "";
  return isIP(forwarded) === 0
    ? null
    : getIP(request, { advanced: { ipAddress: ipAddressOptions } });
}

/** Better Auth's endpoint a signed-in person changes their password with. */
export const changePasswordPath = "/change-password";

/**
 * FPR's rules on `/change-password`, whatever the client sends: anonymous
 * viewers, who have no password, are refused with `forbidden`, and a change
 * always ends the person's other sessions.
 */
const changePasswordRules = createAuthMiddleware(async (ctx) => {
  if (ctx.path !== changePasswordPath) {
    return;
  }
  const session = await getSessionFromCtx(ctx);
  if (session?.user.role === Role.anonymous) {
    throw new APIError("FORBIDDEN", {
      code: "forbidden",
      message: "Anonymous viewers have no password",
    });
  }
  const body: unknown = ctx.body;
  return {
    context: {
      body: {
        ...(typeof body === "object" && body !== null ? body : {}),
        revokeOtherSessions: true,
      },
    },
  };
});

/** Passwords are 12 to 128 characters long. */
export const passwordLength = { min: 12, max: 128 } as const;

export interface CreateAuthOptions {
  /** The process's pool. Better Auth reads and writes through it. */
  db: Db;
  /** `BETTER_AUTH_SECRET`. */
  secret: string;
  /** `PUBLIC_URL`: the only origin Better Auth trusts. */
  baseURL: string;
  /** Where Better Auth's warnings and errors go, as pino lines. */
  logger?: Logger;
}

/**
 * Better Auth for FPR: email and password only, with no public sign-up and
 * no profile edits of its own. Sessions are HTTP-only, `Secure`,
 * `SameSite=Lax` cookies that last 30 days and are extended on use. Writes
 * are accepted from `PUBLIC_URL` alone, and password sign-ins are
 * rate-limited per client address, read from the `X-Forwarded-For` that
 * `web` sets. A request without one is not rate-limited.
 *
 * A session starts only for a person whose access key gives access, so a
 * person whose access ended is refused at sign-in with `access_ended`.
 *
 * Better Auth names its columns itself, so it gets the pool without the
 * camelCase plugin, which would rename the rows it reads back.
 */
export function createAuth({ db, secret, baseURL, logger }: CreateAuthOptions) {
  let missingAddressLogged = false;

  /**
   * A rate limit rule kept per client address: `rule`, or the rule Better
   * Auth would apply. A request without a client address is not limited, so
   * one shared count never locks every client out. The first such request
   * is logged as an error.
   */
  const perClientAddress =
    (rule?: BetterAuthRateLimitRule) =>
    (request: Request, current: BetterAuthRateLimitRule) => {
      if (clientAddress(request) !== null) {
        return rule ?? current;
      }
      if (!missingAddressLogged) {
        missingAddressLogged = true;
        logger?.error(
          { path: new URL(request.url).pathname },
          "rate limit skipped: the request has no client address in X-Forwarded-For",
        );
      }
      return false;
    };

  return betterAuth({
    ...authSchema,
    ...(logger === undefined
      ? {}
      : {
          logger: {
            level: "warn",
            log: (level, message, ...args: unknown[]) => {
              logger[level](args.length > 0 ? { args } : {}, message);
            },
          },
        }),
    secret,
    baseURL,
    basePath: authBasePath,
    trustedOrigins: [baseURL],
    database: { db: db.withoutPlugins(), type: "postgres" },
    emailAndPassword: {
      enabled: true,
      disableSignUp: true,
      minPasswordLength: passwordLength.min,
      maxPasswordLength: passwordLength.max,
    },
    session: {
      ...authSchema.session,
      expiresIn: sessionMaxAgeSeconds,
      updateAge: sessionUpdateAgeSeconds,
    },
    // Better Auth turns these off in tests and development by default. They
    // stay on everywhere, so the tests see what production does. The first
    // rule matching a path applies: sign-in, then every other path.
    rateLimit: {
      enabled: true,
      storage: "memory",
      customRules: {
        "/sign-in/*": perClientAddress(signInRateLimit),
        "/**": perClientAddress(),
      },
    },
    advanced: {
      ...authSchema.advanced,
      ipAddress: ipAddressOptions,
      disableOriginCheck: false,
      useSecureCookies: true,
      defaultCookieAttributes: {
        httpOnly: true,
        secure: true,
        sameSite: "lax",
      },
    },
    databaseHooks: {
      session: {
        create: {
          before: async (session) => {
            if (!(await accessKeys.hasAccess(db, session.userId))) {
              throw new APIError("UNAUTHORIZED", {
                code: "access_ended",
                message: "Your access has ended",
              });
            }
          },
        },
      },
    },
    hooks: { before: changePasswordRules },
    // A person's profile changes through PATCH /me, which checks it.
    disabledPaths: ["/update-user"],
  });
}

export type Auth = ReturnType<typeof createAuth>;
